#!/usr/bin/env python3
"""patch_portofino_floors_tipfix.py — Per-floor rings + S pyramid fix.

REMPLACE patch_portofino_floors.py (ne pas utiliser l'ancien).

1) FLOORS: 42 horizontal floor rings (cylinder octagon + wing pentagons),
   segments 0-85 and 95-128.5 with wings, crown 128.5-140.5 cylinder-only,
   break zone 85-95 clean. One knob: FLOOR_PITCH (3.0 m default, real
   building 44 storeys/~145 m). Rings at width 0.35. RENDER_FLOORS=False
   reverts. Edges 225 -> 1146.

2) S PYRAMID FIX: the S roof rendered flat because the pyramid tip used the
   LM z, and 'Portofino Tower (S)' is a GEOMETRIC LM (equilateral from
   NW+NE) at wall-top height z=143.07 < Z_PEAK_WALL 143.5. The LM must NOT
   be moved: Port (LEAK) + Port (B) + 2 others mark it and their rays pass
   at ~143 (raising it costs Port +6.8'). The mesh now uses a per-branch
   tip_z, with a synthetic S tip at mean(NW,NE)=145.54. All three pyramids
   verified pointy in sandbox render from Port pose.

Idempotent (sentinels). Dry-run par defaut, --apply pour ecrire.
Backup: PortofinoTower.py.bak_floors_tipfix
Apres --apply: python3 tools/extract_mesh_edges.py
"""
import os, shutil, sys

PROJ = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TARGET = os.path.join(PROJ, "PortofinoTower.py")
APPLY = "--apply" in sys.argv

src = open(TARGET).read()
has_floors = "RENDER_FLOORS" in src
has_tip = "tip_z" in src
if has_floors and has_tip:
    print("SKIP: floors + tip fix deja appliques (idempotent)")
    sys.exit(0)
state = f"floors={'OK' if has_floors else 'manquant'}, tip_fix={'OK' if has_tip else 'manquant'}"
if not APPLY:
    print(f"WOULD APPLY ({state}): PortofinoTower.py -> floors + S tip fix (225->1146 edges)")
    print("DRY-RUN: rien ecrit. Relance avec --apply.")
    sys.exit(0)
shutil.copy(TARGET, TARGET + ".bak_floors_tipfix")
open(TARGET, "w").write("\"\"\"\nPortofinoTower.py \u2014 standalone trifoliate tower mesh (cylinder + 3 radial wings).\nAdapted from install_portofino_class.py but kept OUT of the vendored gtamaplib.py.\nAnchored on real LMs Portofino Tower (NW)/(NE)/(S). Scale calibrated to measured\ngeometry: dist centroid->wing-peak = 18m, cylinder box ~485px ~= 36m diam (R~18m),\nheight z_top ~= 142.\n\"\"\"\nimport math\nimport numpy as np\n\n\nclass PortofinoTower:\n    color = '#a78bfa'  # violet, distinct from other meshes\n\n    # Heights (m) \u2014 z_top matches real peaks (~142)\n    Z_PEAK_TOP  = 147.5\n    Z_PEAK_WALL = 143.5   # top of peak-box walls (LM z - 2m); pyramid roof goes up to LM\n    Z_CYL_TOP   = 140.5\n    Z_PENT_TOP  = 128.5\n    Z_BREAK_TOP = 95.0\n    Z_BASE_TOP  = 85.0\n    Z_GROUND    = 0.0\n\n    # Scale (m) \u2014 calibrated to satellite reference (1px ~= 0.074m)\n    R_CYLINDER_BASE = 20.75   # cylinder radius = LM dist from centroid (retriangulated)\n    SIDE_FRONT_BASE = 9.7     # (legacy) outer side\n    SIDE_FRONT = 6.0          # tip-to-shoulder radial depth (front faces)\n    SIDE_SIDE  = 9.7          # shoulder full width\n    SIDE_INNER = 9.0          # base width against the cylinder\n    WING_ROT = -45.0\n    PEAK_BOX_NE_OFFSET = -22.5   # NE peak box rotation offset (deg), tune via UI wireframe\n    PENTAGON_NE_OFFSET = -5.0 # NE pentagon rotation offset (deg); 180 = current behaviour\n    PEAK_BOX_SIDE   = 8.6     # inner (green) square side: 116px*0.074\n\n    # \u2500\u2500 Per-floor rings (2026-06-10) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    # Horizontal cross-section rings at every floor: alignment with the\n    # window bands in leak frames lets us tune ONE knob (FLOOR_PITCH) via\n    # the UI wireframe, same workflow as PEAK_BOX_NE_OFFSET. Real Portofino\n    # Tower is 44 storeys / ~145 m -> ~3.0 m pitch as starting value.\n    RENDER_FLOORS = True      # one-flag revert if UI perf suffers\n    FLOOR_PITCH   = 3.0       # metres between floor slabs \u2014 TUNE THIS\n    # (start_z, end_z, with_wings): break zone 85-95 skipped (mechanical/\n    # transition, no window bands); crown 128.5-140.5 is cylinder-only.\n    FLOOR_SEGMENTS = [\n        (Z_GROUND,    Z_BASE_TOP, True),\n        (Z_BREAK_TOP, Z_PENT_TOP, True),\n        (Z_PENT_TOP,  Z_CYL_TOP,  False),\n    ]\n\n    def __init__(self, md, ml=None):\n        self.md = md\n        self.ml = ml\n        nw = md.landmarks['Portofino Tower (NW)']\n        ne = md.landmarks['Portofino Tower (NE)']\n        s  = md.landmarks['Portofino Tower (S)']\n        self.nw = np.array(nw, dtype=float)\n        self.ne = np.array(ne, dtype=float)\n        self.s  = np.array(s,  dtype=float)\n        self.centroid_xy = (self.nw[:2] + self.ne[:2] + self.s[:2]) / 3\n        self.branch_peaks = {'NW': self.nw, 'NE': self.ne, 'S': self.s}\n\n        # Pyramid tip z per branch. NW/NE LMs are real triangulated peak tips\n        # (~145.5). The S LM is GEOMETRIC (equilateral from NW+NE) and its z\n        # (~143.1) sits at wall-top height \u2014 consistent with the Port LEAK ray\n        # through the 'Portofino Tower (S)' marking (raising the LM costs\n        # Port +6.8'). So: do NOT move the LM; give the MESH a synthetic S tip\n        # at the mean of the two real peaks so the pyramid renders like the\n        # others (verified pointy in leak frames).\n        self.tip_z = {\n            'NW': float(self.nw[2]),\n            'NE': float(self.ne[2]),\n            'S':  (float(self.nw[2]) + float(self.ne[2])) / 2,\n        }\n\n        self.PENT_LEVELS = [\n            ('B', self.Z_GROUND,    1.6),\n            ('K', self.Z_BASE_TOP,  1.6),\n            ('L', self.Z_BREAK_TOP, 1.5),\n            ('P', self.Z_PENT_TOP,  1.6),\n        ]\n        self.CYL_LEVELS = [\n            ('B',  self.Z_GROUND,    1.0),\n            ('K',  self.Z_BASE_TOP,  1.0),\n            ('L',  self.Z_BREAK_TOP, 1.0),\n            ('P',  self.Z_PENT_TOP,  1.0),\n            ('CT', self.Z_CYL_TOP,   1.0),\n        ]\n        self.PEAK_BOX_LEVELS = [('PB', self.Z_PENT_TOP), ('PT', self.Z_PEAK_WALL)]\n\n        # Floor levels: ('Fxx', z, pent_scale, with_wings). Wing scale is\n        # interpolated between the bounding named PENT_LEVELS so floor rings\n        # stay flush with the existing silhouette (B/K=1.6, L=1.5, P=1.6).\n        self.FLOOR_LEVELS = []\n        if self.RENDER_FLOORS:\n            named = [(z, s) for _, z, s in self.PENT_LEVELS]  # sorted by build order\n\n            def pent_scale_at(z):\n                for (z0, s0), (z1, s1) in zip(named, named[1:]):\n                    if z0 <= z <= z1:\n                        t = 0.0 if z1 == z0 else (z - z0) / (z1 - z0)\n                        return s0 + t * (s1 - s0)\n                return named[-1][1]\n\n            idx = 0\n            for z_start, z_end, with_wings in self.FLOOR_SEGMENTS:\n                n = int((z_end - z_start) / self.FLOOR_PITCH)\n                for k in range(1, n + 1):\n                    z = z_start + k * self.FLOOR_PITCH\n                    if z >= z_end - 0.25:   # named level already draws this ring\n                        continue\n                    self.FLOOR_LEVELS.append(\n                        (f'F{idx:02d}', z, pent_scale_at(z), with_wings))\n                    idx += 1\n\n        self.pent = {}\n        self.cyl  = {}\n        self.pbox = {}\n        self._build_geometry()\n\n    def _pentagon(self, peak_xyz, z, scale=1.0, br_name=None):\n        # Wing extends OUTWARD from the cylinder edge (the LM sits at the\n        # inner base of the wing, on the cylinder rim). Seen from above:\n        #   innerL/innerR : base, at the LM radius (cylinder rim)\n        #   sideL/sideR   : shoulders, further out, widest\n        #   peak          : outer tip (furthest from centre)\n        lm_xy = peak_xyz[:2]\n        radial = lm_xy - self.centroid_xy\n        lm_dist = np.linalg.norm(radial)          # ~18m (cylinder rim)\n        radial_unit = radial / lm_dist\n        _wr = self.WING_ROT + (self.PENTAGON_NE_OFFSET if br_name == 'NE' else 0.0)\n        _th = math.radians(_wr)\n        _c, _sn = math.cos(_th), math.sin(_th)\n        radial_unit = np.array([radial_unit[0]*_c - radial_unit[1]*_sn,\n                                radial_unit[0]*_sn + radial_unit[1]*_c])\n        perp = np.array([-radial_unit[1], radial_unit[0]])\n\n        WING_DEPTH = 9.0 * scale                 # how far the wing sticks out\n        SHOULDER_OUT = 4.5 * scale                # shoulder distance from base\n        inner_half = (self.SIDE_INNER / 2) * scale\n        side_half  = (self.SIDE_SIDE  / 2) * scale\n\n        base_pos = lm_xy                                          # at LM (cyl rim)\n        side_pos = lm_xy + radial_unit * SHOULDER_OUT\n        peak_pos = lm_xy + radial_unit * WING_DEPTH\n\n        innerL = base_pos + perp * inner_half\n        innerR = base_pos - perp * inner_half\n        sideL  = side_pos + perp * side_half\n        sideR  = side_pos - perp * side_half\n        return {\n            'innerL': (innerL[0], innerL[1], z),\n            'innerR': (innerR[0], innerR[1], z),\n            'sideL':  (sideL[0],  sideL[1],  z),\n            'sideR':  (sideR[0],  sideR[1],  z),\n            'peak':   (peak_pos[0], peak_pos[1], z),\n        }\n\n    def _peak_box(self, peak_xyz, z, br_name=None):\n        peak_xy = peak_xyz[:2]\n        radial = peak_xy - self.centroid_xy\n        radial_unit = radial / np.linalg.norm(radial)\n        # Box corner-facing: radial rotated 45deg. NE branch needs an extra\n        # offset (like _pentagon's +180) because its peak box was visibly\n        # mis-oriented vs NW/S. PEAK_BOX_NE_OFFSET tunes it (see UI wireframe).\n        _pb_rot = 45.0 + (self.PEAK_BOX_NE_OFFSET if br_name == 'NE' else 0.0)\n        _th = math.radians(_pb_rot)\n        _c, _sn = math.cos(_th), math.sin(_th)\n        radial_unit = np.array([radial_unit[0]*_c - radial_unit[1]*_sn,\n                                radial_unit[0]*_sn + radial_unit[1]*_c])\n        perp = np.array([-radial_unit[1], radial_unit[0]])\n        half = self.PEAK_BOX_SIDE / 2\n        outer = peak_xy + radial_unit * half\n        inner = peak_xy - radial_unit * half\n        return {\n            'pbOL': (outer[0] + perp[0]*half, outer[1] + perp[1]*half, z),\n            'pbOR': (outer[0] - perp[0]*half, outer[1] - perp[1]*half, z),\n            'pbIL': (inner[0] + perp[0]*half, inner[1] + perp[1]*half, z),\n            'pbIR': (inner[0] - perp[0]*half, inner[1] - perp[1]*half, z),\n        }\n\n    def _cylinder(self, z, scale=1.0):\n        R = self.R_CYLINDER_BASE * scale\n        pts = {}\n        for i in range(8):\n            a = i * math.pi / 4\n            x = self.centroid_xy[0] + R * math.cos(a)\n            y = self.centroid_xy[1] + R * math.sin(a)\n            pts[f'cyl{i}'] = (x, y, z)\n        return pts\n\n    def _build_geometry(self):\n        for code, z, scale in self.PENT_LEVELS:\n            for br_name, peak in self.branch_peaks.items():\n                for c_name, xyz in self._pentagon(peak, z, scale, br_name).items():\n                    self.pent[(code, br_name, c_name)] = xyz\n        for code, z, scale in self.CYL_LEVELS:\n            for c_name, xyz in self._cylinder(z, scale).items():\n                self.cyl[(code, c_name)] = xyz\n        for code, z in self.PEAK_BOX_LEVELS:\n            for br_name, peak in self.branch_peaks.items():\n                for c_name, xyz in self._peak_box(peak, z, br_name).items():\n                    self.pbox[(code, br_name, c_name)] = xyz\n        # floor rings reuse the exact same cross-sections (cyl scale 1.0)\n        for code, z, pscale, with_wings in self.FLOOR_LEVELS:\n            for c_name, xyz in self._cylinder(z, 1.0).items():\n                self.cyl[(code, c_name)] = xyz\n            if with_wings:\n                for br_name, peak in self.branch_peaks.items():\n                    for c_name, xyz in self._pentagon(peak, z, pscale, br_name).items():\n                        self.pent[(code, br_name, c_name)] = xyz\n\n    def render_on_camera(self, cam):\n        color = self.color\n        thin = 0.5\n        bold = 1.0\n\n        cyl_codes = [code for code, _, _ in self.CYL_LEVELS]\n        for i in range(8):\n            for j in range(len(cyl_codes) - 1):\n                c1 = self.cyl[(cyl_codes[j],     f'cyl{i}')]\n                c2 = self.cyl[(cyl_codes[j + 1], f'cyl{i}')]\n                cam.render_line((c1, c2), color, thin)\n        for code in cyl_codes:\n            for i in range(8):\n                c1 = self.cyl[(code, f'cyl{i}')]\n                c2 = self.cyl[(code, f'cyl{(i + 1) % 8}')]\n                cam.render_line((c1, c2), color, thin)\n\n        pent_codes = [code for code, _, _ in self.PENT_LEVELS]\n        pent_corners = ['innerL', 'sideL', 'peak', 'sideR', 'innerR']\n        for br_name in ('NW', 'NE', 'S'):\n            for corner in pent_corners:\n                for j in range(len(pent_codes) - 1):\n                    p1 = self.pent[(pent_codes[j],     br_name, corner)]\n                    p2 = self.pent[(pent_codes[j + 1], br_name, corner)]\n                    cam.render_line((p1, p2), color, bold if corner.startswith('front') else thin)\n            for code in pent_codes:\n                for k in range(5):\n                    a = pent_corners[k]; b = pent_corners[(k + 1) % 5]\n                    p1 = self.pent[(code, br_name, a)]\n                    p2 = self.pent[(code, br_name, b)]\n                    cam.render_line((p1, p2), color, thin)\n\n        pbox_corners = ['pbOL', 'pbOR', 'pbIR', 'pbIL']\n        # \u2500\u2500 floor rings (thin horizontal cross-sections, no new verticals) \u2500\u2500\n        floor_w = 0.35\n        pent_corners_ring = ['innerL', 'sideL', 'peak', 'sideR', 'innerR']\n        for code, _z, _ps, with_wings in self.FLOOR_LEVELS:\n            for i in range(8):\n                c1 = self.cyl[(code, f'cyl{i}')]\n                c2 = self.cyl[(code, f'cyl{(i + 1) % 8}')]\n                cam.render_line((c1, c2), color, floor_w)\n            if with_wings:\n                for br_name in ('NW', 'NE', 'S'):\n                    for k in range(5):\n                        a = pent_corners_ring[k]; b = pent_corners_ring[(k + 1) % 5]\n                        p1 = self.pent[(code, br_name, a)]\n                        p2 = self.pent[(code, br_name, b)]\n                        cam.render_line((p1, p2), color, floor_w)\n        for br_name in ('NW', 'NE', 'S'):\n            for corner in pbox_corners:\n                p1 = self.pbox[('PB', br_name, corner)]\n                p2 = self.pbox[('PT', br_name, corner)]\n                cam.render_line((p1, p2), color, bold)\n            for code in [c for c, _ in self.PEAK_BOX_LEVELS]:\n                for k in range(4):\n                    a = pbox_corners[k]; b = pbox_corners[(k + 1) % 4]\n                    p1 = self.pbox[(code, br_name, a)]\n                    p2 = self.pbox[(code, br_name, b)]\n                    cam.render_line((p1, p2), color, bold)\n            # pyramid roof: 4 wall-top corners (PT) -> per-branch tip\n            # (tip_z: S uses synthetic height, see __init__)\n            tip = self.branch_peaks[br_name]\n            tip_pt = (float(tip[0]), float(tip[1]), self.tip_z[br_name])\n            for corner in pbox_corners:\n                base = self.pbox[('PT', br_name, corner)]\n                cam.render_line((base, tip_pt), color, bold)\n        return self\n")
print(f"WRITTEN: {TARGET} (backup .bak_floors_tipfix) [{state} -> les deux OK]")
print("Next: python3 tools/extract_mesh_edges.py")
